const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

const root = path.resolve(__dirname, '..');
const output = path.join(root, 'src', 'generated', 'sdk-authoring-reference.js');
const exportOutput = path.join(root, 'src', 'generated', 'dkds-sdk-export.zip');

const explicit = [
  'sdk/contract.json',
  'sdk/plugin-manifest.schema.json',
  'sdk/plugin-api.d.ts',
  'sdk/declarative-plugin.schema.json',
  'sdk/DECLARATIVE_PLUGIN_GENERATOR.md',
  'sdk/python/dkds_plugin_gen.py',
  'sdk/python/dkds_source_import.py',
  'sdk/python/dkds_source_workflow.py',
  'sdk/python/dkds_portable_task.py',
  'sdk/README.md',
  'sdk/DATA_ARTIFACT_ACCESS.md',
  'sdk/SCIENTIFIC_UNITS.md',
  'sdk/VIEWPORT_LINKING.md',
  'sdk/CROSS_VIEW_SELECTION.md',
  'sdk/DOMAIN_COMMANDS.md',
  'sdk/TASK_RUNNER.md',
  'sdk/ACQUISITION_ORDER.md',
  'sdk/STREAMING_IMPORT.md',
  'sdk/PLATFORM_PRESENTATION.md',
  'sdk/GRID_LAYOUT.md',
  'sdk/GROUP_AREA.md',
  'sdk/THEME_CONTRACT.md',
  'sdk/theme-contract.js',
  'sdk/theme-coverage-contract.js',
  'sdk/TOP_WORKSPACES.md',
  'sdk/TOOL_PLUGINS.md',
  'sdk/layout-contract.js',
  'sdk/tools/dkds-plugin.js',
  'docs/PLUGIN_API.md',
  'docs/PLUGIN_PACKAGES.md',
  'docs/PLUGIN_UI_INFRASTRUCTURE.md',
  'docs/PLUGIN_WORKSPACE_DESIGN_SYSTEM.md',
  'docs/WORKSPACE_PLUGIN_API.md',
  'docs/SUPER_TOP_WORKSPACE_CONTRACT_CN.md',
  'docs/AI_PLUGIN_DEVELOPMENT_GUIDE.md',
  'docs/PARAMETER_SCHEMA.md',
  'docs/DATA_MODEL.md',
  'docs/SCIENTIFIC_TRANSFORMS.md',
  'docs/ANALYSIS_WORKBENCH_ARCHITECTURE.md',
  'docs/STUDIO_KERNEL_AGENT_MCP.md'
];

function walk(rel) {
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) return [];
  const stat = fs.statSync(abs);
  if (stat.isFile()) return [rel.replaceAll('\\', '/')];
  return fs.readdirSync(abs, { withFileTypes: true })
    .filter(entry => entry.name !== '__pycache__' && !/\.py[co]$/i.test(entry.name))
    .sort((a, b) => a.name.localeCompare(b.name))
    .flatMap(entry => walk(path.join(rel, entry.name)));
}

const paths = [...new Set([...explicit, ...walk('sdk/templates')])]
  .filter(rel => fs.existsSync(path.join(root, rel)) && fs.statSync(path.join(root, rel)).isFile())
  .sort((a, b) => a.localeCompare(b));

const files = {};
const meta = [];
for (const rel of paths) {
  const content = fs.readFileSync(path.join(root, rel), 'utf8').replace(/\r\n/g, '\n');
  files[rel] = content;
  meta.push({
    path: rel,
    bytes: Buffer.byteLength(content),
    lines: content.length ? content.split('\n').length : 0,
    category: rel.startsWith('sdk/templates/') ? 'template' : rel.startsWith('sdk/') ? 'sdk' : 'guide'
  });
}

const contract = JSON.parse(files['sdk/contract.json']);
const source = `/* AUTO-GENERATED by scripts/generate-sdk-authoring-reference.js. Do not edit manually. */\n(() => {\n  if (window.DKDSSdkAuthoringReference) return;\n  const FILES = Object.freeze(${JSON.stringify(files)});\n  const META = Object.freeze(${JSON.stringify(meta)}.map(Object.freeze));\n  const normalizePath = value => String(value || '').replaceAll('\\\\','/').replace(/^\\.\\//,'').replace(/^\\/+/, '');\n  const clone = value => { try { return structuredClone(value); } catch { return JSON.parse(JSON.stringify(value)); } };\n  function describe(){\n    const categories={}; let bytes=0, lines=0;\n    for(const row of META){categories[row.category]=(categories[row.category]||0)+1;bytes+=row.bytes;lines+=row.lines;}\n    return {name:'DK Data Studio SDK Authoring Reference',sdkVersion:${JSON.stringify(contract.sdkVersion)},pluginApiVersion:${JSON.stringify(contract.pluginApiVersion)},packageSchema:${JSON.stringify(contract.packageSchema)},minimumAppVersion:${JSON.stringify(contract.minimumAppVersion)},fileCount:META.length,bytes,lines,categories,usage:'Use list/search first, then read the exact SDK, schema, type definition, guide or template needed for plugin authoring.'};\n  }\n  function list(options={}){\n    const prefix=normalizePath(options.prefix||''); const category=String(options.category||'').trim();\n    return META.filter(row=>(!prefix||row.path.startsWith(prefix))&&(!category||row.category===category)).map(clone);\n  }\n  function read(pathValue,options={}){\n    const p=normalizePath(pathValue); if(!Object.prototype.hasOwnProperty.call(FILES,p)) throw new Error('SDK authoring reference file not found: '+p);\n    const source=FILES[p], rows=source.split('\\n');\n    const start=Math.max(1,Math.min(rows.length,Number(options.startLine)||1));\n    const requestedEnd=Number(options.endLine); const end=Math.max(start,Math.min(rows.length,Number.isFinite(requestedEnd)&&requestedEnd>0?requestedEnd:rows.length));\n    const maxChars=Math.max(256,Math.min(500000,Number(options.maxChars)||120000));\n    let content=rows.slice(start-1,end).join('\\n'), truncated=false;\n    if(content.length>maxChars){content=content.slice(0,maxChars);truncated=true;}\n    return {path:p,startLine:start,endLine:end,totalLines:rows.length,content,truncated};\n  }\n  function search(queryValue,options={}){\n    const query=String(queryValue||'').trim(); if(!query) throw new Error('SDK authoring search query is required.');\n    const tokens=query.toLowerCase().split(/\\s+/).filter(Boolean);\n    const pathFilter=Array.isArray(options.paths)?new Set(options.paths.map(normalizePath)):null;\n    const limit=Math.max(1,Math.min(80,Number(options.limit)||24)); const context=Math.max(0,Math.min(8,Number(options.contextLines)||2));\n    const results=[];\n    for(const row of META){\n      if(pathFilter&&![...pathFilter].some(p=>row.path===p||row.path.startsWith(p))) continue;\n      const lines=FILES[row.path].split('\\n');\n      for(let i=0;i<lines.length;i++){const lower=lines[i].toLowerCase();let score=0;for(const token of tokens)if(lower.includes(token))score++;if(!score)continue;\n        const from=Math.max(0,i-context),to=Math.min(lines.length,i+context+1);results.push({path:row.path,line:i+1,score,snippet:lines.slice(from,to).join('\\n')});\n      }\n    }\n    return results.sort((a,b)=>b.score-a.score||a.path.localeCompare(b.path)||a.line-b.line).slice(0,limit);\n  }\n  window.DKDSSdkAuthoringReference=Object.freeze({VERSION:${JSON.stringify(contract.sdkVersion)},PLUGIN_API_VERSION:${JSON.stringify(contract.pluginApiVersion)},describe,list,read,search,has:pathValue=>Object.prototype.hasOwnProperty.call(FILES,normalizePath(pathValue))});\n})();\n`;

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(buffer) {
  let crc = 0xffffffff;
  for (const byte of buffer) crc = CRC_TABLE[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function makeStoredZip(entries) {
  const locals = [];
  const centrals = [];
  let offset = 0;
  for (const entry of entries) {
    const name = Buffer.from(String(entry.name).replaceAll('\\', '/'), 'utf8');
    const data = Buffer.isBuffer(entry.data) ? entry.data : Buffer.from(String(entry.data ?? ''), 'utf8');
    const crc = crc32(data);
    const local = Buffer.alloc(30 + name.length);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0x0800, 6);
    local.writeUInt16LE(0, 8);
    local.writeUInt16LE(0, 10);
    local.writeUInt16LE(33, 12); // 1980-01-01, deterministic ZIP timestamp.
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(name.length, 26);
    local.writeUInt16LE(0, 28);
    name.copy(local, 30);
    locals.push(local, data);

    const central = Buffer.alloc(46 + name.length);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4);
    central.writeUInt16LE(20, 6);
    central.writeUInt16LE(0x0800, 8);
    central.writeUInt16LE(0, 10);
    central.writeUInt16LE(0, 12);
    central.writeUInt16LE(33, 14);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(data.length, 20);
    central.writeUInt32LE(data.length, 24);
    central.writeUInt16LE(name.length, 28);
    central.writeUInt16LE(0, 30);
    central.writeUInt16LE(0, 32);
    central.writeUInt16LE(0, 34);
    central.writeUInt16LE(0, 36);
    central.writeUInt32LE(0, 38);
    central.writeUInt32LE(offset, 42);
    name.copy(central, 46);
    centrals.push(central);
    offset += local.length + data.length;
  }
  const centralOffset = offset;
  const centralSize = centrals.reduce((sum, part) => sum + part.length, 0);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(0, 4);
  end.writeUInt16LE(0, 6);
  end.writeUInt16LE(entries.length, 8);
  end.writeUInt16LE(entries.length, 10);
  end.writeUInt32LE(centralSize, 12);
  end.writeUInt32LE(centralOffset, 16);
  end.writeUInt16LE(0, 20);
  return Buffer.concat([...locals, ...centrals, end]);
}

function buildSdkExport() {
  const publicDocs = explicit.filter(rel => rel.startsWith('docs/'));
  const exportPaths = [...new Set([...walk('sdk'), ...publicDocs])]
    .filter(rel => fs.existsSync(path.join(root, rel)) && fs.statSync(path.join(root, rel)).isFile())
    .sort((a, b) => a.localeCompare(b));
  const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
  const rows = exportPaths.map(rel => {
    const data = fs.readFileSync(path.join(root, rel));
    return {path:rel,bytes:data.length,sha256:crypto.createHash('sha256').update(data).digest('hex'),data};
  });
  const manifest = {
    name:'DK Data Studio Plugin SDK Export',
    appVersion:String(pkg.version||''),
    sdkVersion:String(contract.sdkVersion||''),
    pluginApiVersion:String(contract.pluginApiVersion||''),
    themeContractVersion:String(contract.themeContractVersion||''),
    minimumAppVersion:String(contract.minimumAppVersion||''),
    fileCount:rows.length,
    files:rows.map(({path:rel,bytes,sha256})=>({path:rel,bytes,sha256}))
  };
  const startHere = `# DK Data Studio SDK — AI START HERE\n\nThis archive is exported directly from DK Data Studio ${manifest.appVersion} and contains the complete public plugin SDK plus the public authoring guides bundled for AI-assisted plugin development.\n\nCurrent contracts:\n- SDK: ${manifest.sdkVersion}\n- Plugin API: ${manifest.pluginApiVersion}\n- Theme Contract: ${manifest.themeContractVersion}\n- Minimum app version declared by the SDK: ${manifest.minimumAppVersion}\n\nRecommended reading order for an AI coding assistant:\n1. sdk/README.md\n2. sdk/contract.json\n3. sdk/plugin-api.d.ts\n4. sdk/plugin-manifest.schema.json\n5. docs/AI_PLUGIN_DEVELOPMENT_GUIDE.md\n6. sdk/DECLARATIVE_PLUGIN_GENERATOR.md when generating a plugin from Python/declarative source\n7. the specific SDK guide and template relevant to the requested plugin\n\nTreat the files in this archive as the authoritative current contract. Do not invent deprecated aliases, compatibility shims, private Core APIs, or platform-specific shortcuts that are not documented here.\n`;
  const entries = [
    {name:'AI_START_HERE.md',data:startHere},
    {name:'SDK_MANIFEST.json',data:JSON.stringify(manifest,null,2)+'\n'},
    ...rows.map(row=>({name:row.path,data:row.data}))
  ];
  const zip = makeStoredZip(entries);
  fs.writeFileSync(exportOutput, zip);
  return {zip,manifest};
}

fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, source, 'utf8');
const sdkExport = buildSdkExport();
console.log(`Generated ${path.relative(root, output)} with ${meta.length} authoring files (${Buffer.byteLength(source)} bytes).`);
console.log(`Generated ${path.relative(root, exportOutput)} with ${sdkExport.manifest.fileCount} SDK/guide files (${sdkExport.zip.length} bytes).`);
